        "比較対象を集める::周辺成約事例、募集事例、類似アセット、競合物件、賃料水準、土地価格、建築費を確認します。公開情報だけで足りない場合は、仲介会社、PM、金融機関、専門家ヒアリングも組み合わせます。",
