        "リスクを価格に反映する::境界、遵法性、修繕、テナント退去、賃料下落、金利上昇、工事費上昇などを価格調整や条件交渉に反映します。リスクを見つけても価格へ反映できなければ、投資判断上の意味が薄くなります。",
