        "データと根拠の残し方::買付前には、標準シナリオ、保守シナリオ、上振れシナリオを作ります。賃料が下がった場合、空室期間が延びた場合、金利が上がった場合、出口Cap Rateが上昇した場合に、投資判断がどう変わるかを確認します。価格レンジを持つと、交渉時に上限価格を説明しやすくなります。",
