      "message": "接道やインフラは、買主が建物を使えるか、建て替えられるか、融資を受けられるかに直結します。私道負担、通行承諾、掘削承諾、上下水道管の越境や共有管は、登記・現地・役所・関係者確認をつなげて整理する必要があります。",
